with customers as(select customer_unique_id,min(purchase_date) as first_purchase,max(purchase_date) as last_purchase,count(*) as frequency,sum(sales) as monetary from {{ ref('fact_orders') }} where order_status='delivered' group by 1), r as(select *, (select max(purchase_date)+1 from {{ ref('fact_orders') }} where order_status='delivered')-last_purchase as recency from customers)
select *, case when recency<=90 and frequency>=3 then 'Champions' when frequency>=2 and recency<=180 then 'Loyal Customers' when recency<=30 then 'New Customers' when recency<=90 then 'Potential Loyalists' when recency<=180 then 'At-Risk Customers' else 'Inactive Customers' end as segment from r
